 <?php $__env->startSection('title','Data Sampah'); ?> <?php $__env->startSection('content'); ?><div class="row g-2 mb-3"><div class="col-md-8"><form class="row g-2"><div class="col"><input class="form-control" name="search" value="<?php echo e(request('search')); ?>" placeholder="Cari sampah"></div><div class="col"><select class="form-select" name="category_id"><option value="">Semua kategori</option><?php $__currentLoopData = $categories; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if(request('category_id')==$c->id): echo 'selected'; endif; ?>><?php echo e($c->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-auto"><button class="btn btn-outline-secondary">Filter</button></div></form></div><div class="col-md-4 text-md-end"><a class="btn btn-success" href="<?php echo e(route('wastes.create')); ?>">+ Tambah Sampah</a></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nama</th><th>Kategori</th><th>Harga/kg</th><th>Stok kg</th><th>Aksi</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $wastes; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $w): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($w->name); ?></td><td><?php echo e($w->category->name); ?></td><td>Rp <?php echo e(number_format($w->price_per_kg,0,',','.')); ?></td><td><?php echo e($w->stock_kg); ?></td><td><a class="btn btn-sm btn-warning" href="<?php echo e(route('wastes.edit',$w)); ?>">Edit</a><form class="d-inline" method="post" action="<?php echo e(route('wastes.destroy',$w)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('delete'); ?><button class="btn btn-sm btn-danger" onclick="return confirm('Hapus?')">Hapus</button></form></td></tr><?php en